//! CSS cascade boundary. Values remain plain data so layout can consume them directly.
use crate::{css::{Stylesheet,Declaration},dom::Node};
#[derive(Clone,Debug,Default)] pub struct ComputedStyle { pub display:Display,pub color:(u8,u8,u8,u8),pub width:Option<f32>,pub height:Option<f32>,pub margin:[f32;4],pub padding:[f32;4],pub font_size:f32,pub font_family:String,pub overflow:String,pub position:String,pub z_index:i32,pub background:(u8,u8,u8,u8),pub opacity:f32 }
#[derive(Clone,Copy,Debug,Default,PartialEq)] pub enum Display{#[default]Block,Inline,None}
pub fn resolve(node:&Node,sheet:&Stylesheet)->ComputedStyle{let mut r=ComputedStyle{color:(0,0,0,255),font_size:16.0,font_family:"sans-serif".into(),overflow:"visible".into(),position:"static".into(),background:(0,0,0,0),opacity:1.0,..Default::default()};let mut best=(0,0,0,0);for rule in &sheet.rules{if crate::css::specificity(&rule.selector)>=(0,0,0)&&rule.selector.trim().eq_ignore_ascii_case("*"){apply(&mut r,&rule.declarations);best=(0,0,0,rule.order)}}for d in &sheet.rules.iter().flat_map(|x|x.declarations.clone()).collect::<Vec<_>>(){if d.property=="display"{apply(&mut r,&[d.clone()]);}}let _=best;let _=node;r}
fn apply(s:&mut ComputedStyle,ds:&[Declaration]){for d in ds{match d.property.as_str(){"display"=>s.display=match d.value.as_str(){"none"=>Display::None,"inline"=>Display::Inline,_=>Display::Block},"width"=>s.width=num(&d.value),"height"=>s.height=num(&d.value),"font-size"=>if let Some(v)=num(&d.value){s.font_size=v},"opacity"=>if let Ok(v)=d.value.parse(){s.opacity=v},"overflow"=>s.overflow=d.value.clone(),"position"=>s.position=d.value.clone(),"z-index"=>if let Ok(v)=d.value.parse(){s.z_index=v},_=>{}}}}
fn num(v:&str)->Option<f32>{v.trim_end_matches("px").parse().ok()}
#[cfg(test)]mod tests{use super::*;#[test]fn defaults(){assert_eq!(ComputedStyle::default().display,Display::Block);}}
